module Spree
  # An invoice, receipt or credit note for an order or a seller payout,
  # whoever made it: uploaded from the issuer's own system, or generated by an
  # extension that writes `source: generated`
  # (docs/plans/6.1-invoices-and-receipts.md).
  #
  # The issuer is whoever sold the goods: a seller order's seller, otherwise
  # the store. An invoice is a record kept for years, so its number, totals and
  # file never change; a correction is a credit note. An upload may be deleted
  # only until the buyer has been sent it.
  class Invoice < Spree.base_class
    include Spree::SingleStoreResource
    include Spree::Metadata
    include Spree::ActedBy

    has_prefix_id :inv

    publishes_lifecycle_events
    publishes_event :sent
    # Someone asked for the invoice to be emailed again. Internal: the email
    # gem answers it, and no webhook endpoint needs it.
    publishes_event :delivery_requested, webhook: false

    KINDS = %w[invoice receipt credit_note].freeze
    SOURCES = %w[uploaded generated].freeze
    ISSUER_TYPES = %w[Spree::Store Spree::Seller].freeze
    CONTENT_TYPES = %w[application/pdf].freeze
    MAX_FILE_SIZE = 10.megabytes

    belongs_to :issuer, polymorphic: true
    belongs_to :order, class_name: 'Spree::Order', optional: true, inverse_of: :invoices
    belongs_to :seller_payout, class_name: 'Spree::SellerPayout', optional: true, inverse_of: :invoices
    belongs_to :original_invoice, class_name: 'Spree::Invoice', optional: true
    # The admin user, seller team member or API key that uploaded it.
    acted_by :uploaded_by

    has_many :credit_notes, class_name: 'Spree::Invoice', foreign_key: :original_invoice_id,
                            inverse_of: :original_invoice, dependent: :restrict_with_error
    has_one :invoice_request, class_name: 'Spree::InvoiceRequest', dependent: :nullify, inverse_of: :invoice

    has_private_document :file, content_types: CONTENT_TYPES, max_size: MAX_FILE_SIZE, required: true

    validates :kind, inclusion: { in: KINDS }
    validates :source, inclusion: { in: SOURCES }
    validates :issuer_type, inclusion: { in: ISSUER_TYPES }
    validates :number, :issued_on, :currency, :total, presence: true
    validates :number, uniqueness: { scope: [:issuer_type, :issuer_id, :kind] }
    validates :total, :net_total, :tax_total, numericality: true, allow_nil: true
    validate :belongs_to_one_parent
    validate :issuer_matches_parent, on: :create
    validate :sign_matches_kind
    validate :original_invoice_on_same_parent, if: :original_invoice
    validate :unchanged_once_created, on: :update

    before_destroy :ensure_deletable, prepend: true

    scope :invoices, -> { where(kind: 'invoice') }
    scope :credit_notes, -> { where(kind: 'credit_note') }
    # What counts as an order having been invoiced: an invoice or a receipt.
    scope :sale_documents, -> { where(kind: %w[invoice receipt]) }
    scope :sent, -> { where.not(sent_at: nil) }

    self.whitelisted_ransackable_attributes = %w[kind source number issued_on supplied_on currency total
                                                 order_id seller_payout_id issuer_type issuer_id created_at sent_at]
    self.whitelisted_ransackable_associations = %w[order seller_payout]

    # The legal seller of an order: its seller when the seller is merchant of
    # record, otherwise the store. A platform-remitted seller's sales are
    # invoiced by the store (the deemed-supplier case).
    #
    # @param order [Spree::Order]
    # @return [Spree::Store, Spree::Seller]
    def self.issuer_for(order)
      seller = order.seller
      seller && seller.tax_remittance != 'platform' ? seller : order.store
    end

    # @return [Boolean]
    def credit_note?
      kind == 'credit_note'
    end

    # @return [Boolean]
    def sent?
      sent_at.present?
    end

    # An upload can be withdrawn until the buyer has it; a generated invoice
    # never can.
    #
    # @return [Boolean]
    def can_be_deleted?
      source == 'uploaded' && !sent?
    end

    # Records that the invoice reached its buyer. The only change an invoice
    # takes after it is created.
    #
    # @return [void]
    def mark_sent!
      update_columns(sent_at: Time.current, updated_at: Time.current)
      publish_event('invoice.sent')
    end

    # The address the invoice is emailed to: the order's buyer, or for a
    # commission invoice the seller's billing contact.
    #
    # @return [String, nil]
    def recipient_email
      return order.email if order

      seller = seller_payout&.seller
      seller&.billing_email.presence || seller&.contact_email
    end

    private

    def belongs_to_one_parent
      return if order_id.present? ^ seller_payout_id.present?

      errors.add(:base, :invoice_parent_required)
    end

    def issuer_matches_parent
      expected = if order
                   self.class.issuer_for(order)
                 elsif seller_payout
                   seller_payout.store
                 end
      return if expected.nil? || issuer.nil? || issuer == expected

      errors.add(:issuer, :invoice_issuer_mismatch)
    end

    def sign_matches_kind
      return if total.nil?

      if credit_note?
        errors.add(:total, :less_than_or_equal_to, count: 0) if total.positive?
      elsif total.negative?
        errors.add(:total, :greater_than_or_equal_to, count: 0)
      end
    end

    def original_invoice_on_same_parent
      return if original_invoice.order_id == order_id && original_invoice.seller_payout_id == seller_payout_id

      errors.add(:original_invoice, :invalid)
    end

    # An invoice is a legal record: once written, only metadata and the sent
    # timestamp may move.
    def unchanged_once_created
      locked = changed - %w[metadata updated_at sent_at]
      locked.each { |attribute| errors.add(attribute, :invoice_immutable) }
      errors.add(:file, :invoice_immutable) if attachment_changes['file']
    end

    def ensure_deletable
      return if can_be_deleted?

      errors.add(:base, :invoice_cannot_be_deleted)
      throw(:abort)
    end
  end
end
